\begin{aligned}
\partial_0h^{\mathrm{TT}}_{ij}
&=\frac{2G}{r}\frac{\mathrm d^3J^{\mathrm{TT}}_{ij}}{\mathrm dt^3},\\
\partial_rh^{\mathrm{TT}}_{ij}
&=-\frac{2G}{r}\frac{\mathrm d^3J^{\mathrm{TT}}_{ij}}{\mathrm dt^3}
